#!/usr/bin/env tsx
/**
 * execute-ultra.ts - Execute Ultra orders on Jupiter
 *
 * Usage:
 *   pnpm execute-ultra --request-id "UUID" --signed-tx "BASE64_SIGNED_TX"
 *
 * This script:
 *   1. Takes the requestId from /ultra/v1/order response
 *   2. Takes the signed transaction (sign with wallet-sign.ts first)
 *   3. POSTs to /ultra/v1/execute
 *   4. Returns execution result
 */

import { Command } from "commander";
import { getApiKey, printApiKeyError, isValidBase64, isValidUUID } from "./utils.js";

const EXECUTE_URL = "https://api.jup.ag/ultra/v1/execute";
const REQUEST_TIMEOUT_MS = 30000;

interface ExecuteOptions {
  requestId: string;
  signedTx: string;
  apiKey?: string;
}

interface ExecuteResponse {
  status: "Success" | "Failed";
  signature?: string;
  error?: string;
  code?: string;
  slot?: number;
  inputAmountResult?: string;
  outputAmountResult?: string;
}

async function executeOrder(options: ExecuteOptions): Promise<void> {
  const apiKey = getApiKey(options.apiKey);

  if (!apiKey) {
    printApiKeyError();
    process.exit(1);
  }

  // Validate inputs
  if (!options.requestId) {
    console.error("Error: --request-id is required");
    console.error("Get the requestId from the /ultra/v1/order response");
    process.exit(1);
  }

  if (!isValidUUID(options.requestId)) {
    console.error("Error: Invalid request ID format. Expected UUID format.");
    process.exit(1);
  }

  if (!options.signedTx) {
    console.error("Error: --signed-tx is required");
    console.error("Sign the transaction first using: pnpm wallet-sign --unsigned-tx ...");
    process.exit(1);
  }

  // Validate base64 format
  if (!isValidBase64(options.signedTx)) {
    console.error("Error: Invalid base64 format for signed transaction");
    process.exit(1);
  }

  const body = {
    requestId: options.requestId,
    signedTransaction: options.signedTx,
  };

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(EXECUTE_URL, {
      method: "POST",
      headers: {
        "x-api-key": apiKey,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    });

    // Check for rate limiting
    if (response.status === 429) {
      const retryAfter = response.headers.get("Retry-After");
      console.error("Error: Rate limited by Jupiter API");
      if (retryAfter) {
        console.error(`Retry after: ${retryAfter} seconds`);
      }
      console.error("\nUltra rate limits scale with your executed swap volume.");
      console.error("See: https://dev.jup.ag/docs/ultra/rate-limit.md");
      process.exit(1);
    }

    let data: ExecuteResponse;
    try {
      data = (await response.json()) as ExecuteResponse;
    } catch (e) {
      console.error("Error: API returned non-JSON response");
      console.error(`Status: ${response.status}`);
      const text = await response.text().catch(() => "Unable to read response");
      console.error(`Body: ${text.slice(0, 500)}`);
      process.exit(1);
    }

    if (!response.ok) {
      console.error(`Error: API returned status ${response.status}`);
      console.error(JSON.stringify(data, null, 2));
      process.exit(1);
    }

    // Output result
    console.log(JSON.stringify(data, null, 2));

    // Additional info to stderr
    if (data.status === "Success" && data.signature) {
      console.error(`\nTransaction successful!`);
      console.error(`Signature: ${data.signature}`);
      console.error(`Explorer: https://solscan.io/tx/${data.signature}`);
    } else if (data.status === "Failed") {
      console.error(`\nTransaction failed!`);
      if (data.error) {
        console.error(`Error: ${data.error}`);
      }
      if (data.code) {
        console.error(`Code: ${data.code}`);
      }
      process.exit(1);
    }
  } catch (error) {
    if (error instanceof Error) {
      if (error.name === "AbortError") {
        console.error(`Error: Request timed out after ${REQUEST_TIMEOUT_MS / 1000} seconds`);
      } else {
        console.error(`Network error: ${error.message}`);
      }
    } else {
      console.error("Unknown error occurred");
    }
    process.exit(1);
  } finally {
    clearTimeout(timeoutId);
  }
}

// CLI setup
const program = new Command();

program
  .name("execute-ultra")
  .description("Execute Ultra orders on Jupiter")
  .requiredOption(
    "-r, --request-id <id>",
    "Request ID from /ultra/v1/order response"
  )
  .requiredOption(
    "-t, --signed-tx <base64>",
    "Base64-encoded signed transaction"
  )
  .option("-k, --api-key <key>", "Jupiter API key (or use JUP_API_KEY env var)")
  .action(executeOrder);

program.parse();

#!/usr/bin/env tsx
/**
 * fetch-api.ts - Fetch data from any Jupiter API endpoint
 *
 * Usage:
 *   pnpm fetch-api --endpoint /ultra/v1/search --params '{"query":"SOL"}'
 *   pnpm fetch-api --endpoint /ultra/v1/order --params '{"inputMint":"So11...","outputMint":"EPjF...","amount":"1000000","taker":"YOUR_WALLET"}'
 *   pnpm fetch-api --endpoint /swap/v1/swap --method POST --body '{"quoteResponse":{...},"userPublicKey":"..."}'
 */

import { Command } from "commander";
import { getApiKey, printApiKeyError } from "./utils.js";

const BASE_URL = "https://api.jup.ag";
const REQUEST_TIMEOUT_MS = 30000;

interface FetchOptions {
  endpoint: string;
  params?: string;
  body?: string;
  method: string;
  apiKey?: string;
}

async function fetchApi(options: FetchOptions): Promise<void> {
  const apiKey = getApiKey(options.apiKey);

  if (!apiKey) {
    printApiKeyError();
    process.exit(1);
  }

  // Build URL with query params for GET requests
  let url = `${BASE_URL}${options.endpoint}`;

  const headers: Record<string, string> = {
    "x-api-key": apiKey,
    "Content-Type": "application/json",
  };

  const fetchOptions: RequestInit = {
    method: options.method.toUpperCase(),
    headers,
  };

  // Handle params for GET or body for POST
  if (options.method.toUpperCase() === "GET" && options.params) {
    try {
      const params = JSON.parse(options.params);
      const searchParams = new URLSearchParams();
      for (const [key, value] of Object.entries(params)) {
        searchParams.append(key, String(value));
      }
      url += `?${searchParams.toString()}`;
    } catch (e) {
      console.error("Error: Invalid JSON in --params");
      console.error("Expected format: '{\"key\":\"value\"}'");
      process.exit(1);
    }
  } else if (options.method.toUpperCase() === "POST") {
    if (options.body) {
      try {
        // Validate JSON
        JSON.parse(options.body);
        fetchOptions.body = options.body;
      } catch (e) {
        console.error("Error: Invalid JSON in --body");
        process.exit(1);
      }
    } else if (options.params) {
      // Allow --params for POST body as well
      try {
        JSON.parse(options.params);
        fetchOptions.body = options.params;
      } catch (e) {
        console.error("Error: Invalid JSON in --params");
        process.exit(1);
      }
    }
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);

  try {
    const response = await fetch(url, { ...fetchOptions, signal: controller.signal });

    // Check for rate limiting
    if (response.status === 429) {
      const retryAfter = response.headers.get("Retry-After");
      console.error("Error: Rate limited by Jupiter API");
      if (retryAfter) {
        console.error(`Retry after: ${retryAfter} seconds`);
      }
      console.error("\nConsider upgrading your API tier at https://portal.jup.ag");
      process.exit(1);
    }

    let data;
    try {
      data = await response.json();
    } catch (e) {
      console.error("Error: API returned non-JSON response");
      console.error(`Status: ${response.status}`);
      const text = await response.text().catch(() => "Unable to read response");
      console.error(`Body: ${text.slice(0, 500)}`);
      process.exit(1);
    }

    if (!response.ok) {
      console.error(`Error: API returned status ${response.status}`);
      console.error(JSON.stringify(data, null, 2));
      process.exit(1);
    }

    // Output JSON to stdout for piping to other tools
    console.log(JSON.stringify(data, null, 2));
  } catch (error) {
    if (error instanceof Error) {
      if (error.name === "AbortError") {
        console.error(`Error: Request timed out after ${REQUEST_TIMEOUT_MS / 1000} seconds`);
      } else {
        console.error(`Network error: ${error.message}`);
      }
    } else {
      console.error("Unknown error occurred");
    }
    process.exit(1);
  } finally {
    clearTimeout(timeoutId);
  }
}

// CLI setup
const program = new Command();

program
  .name("fetch-api")
  .description("Fetch data from any Jupiter API endpoint")
  .requiredOption("-e, --endpoint <path>", "API endpoint path (e.g., /ultra/v1/order)")
  .option("-p, --params <json>", "Query parameters as JSON string (for GET) or body (for POST)")
  .option("-b, --body <json>", "Request body as JSON string (for POST)")
  .option("-m, --method <method>", "HTTP method (GET or POST)", "GET")
  .option("-k, --api-key <key>", "Jupiter API key (or use JUP_API_KEY env var)")
  .action(fetchApi);

program.parse();

#!/usr/bin/env tsx
/**
 * send-transaction.ts - Send signed transactions to Solana RPC
 *
 * Usage:
 *   pnpm send-transaction --signed-tx "BASE64_SIGNED_TX"
 *   pnpm send-transaction --signed-tx "BASE64_SIGNED_TX" --rpc-url "https://your-rpc.com"
 *
 * This script:
 *   1. Takes a signed transaction (base64)
 *   2. Sends it to the specified RPC endpoint
 *   3. Waits for confirmation
 *   4. Returns the transaction signature
 *
 * Use this for Metis swaps or any transaction that needs manual RPC submission.
 * For Ultra swaps, use execute-ultra.ts instead (Jupiter handles RPC internally).
 */

import { Command } from "commander";
import {
  Connection,
  VersionedTransaction,
  SendTransactionError,
} from "@solana/web3.js";

const DEFAULT_RPC_URL = "https://api.mainnet-beta.solana.com";

interface SendOptions {
  signedTx: string;
  rpcUrl?: string;
  skipPreflight?: boolean;
  maxRetries?: string;
}

function getRpcUrl(providedUrl?: string): string {
  if (providedUrl) return providedUrl;
  if (process.env.SOLANA_RPC_URL) return process.env.SOLANA_RPC_URL;
  return DEFAULT_RPC_URL;
}

async function sendTransaction(options: SendOptions): Promise<void> {
  const rpcUrl = getRpcUrl(options.rpcUrl);

  console.error(`Using RPC: ${rpcUrl}`);

  if (rpcUrl === DEFAULT_RPC_URL) {
    console.error("Warning: Using public Solana RPC which is rate-limited.");
    console.error("For production, set SOLANA_RPC_URL to your own RPC endpoint.");
  }

  // Deserialize the transaction
  let transaction: VersionedTransaction;
  try {
    const txBuffer = Buffer.from(options.signedTx, "base64");
    transaction = VersionedTransaction.deserialize(txBuffer);
  } catch (error) {
    console.error("Error: Failed to deserialize transaction");
    console.error("Ensure the transaction is a valid base64-encoded signed VersionedTransaction");
    process.exit(1);
  }

  // Check if transaction is signed
  if (transaction.signatures.length === 0) {
    console.error("Error: Transaction has no signatures");
    console.error("Sign the transaction first using: pnpm wallet-sign --unsigned-tx ...");
    process.exit(1);
  }

  // Create connection
  const connection = new Connection(rpcUrl, "confirmed");

  // Send transaction
  try {
    console.error("Sending transaction...");

    const maxRetries = options.maxRetries ? parseInt(options.maxRetries, 10) : 3;
    if (isNaN(maxRetries) || maxRetries < 0) {
      console.error("Error: --max-retries must be a non-negative integer");
      process.exit(1);
    }

    const signature = await connection.sendTransaction(transaction, {
      skipPreflight: options.skipPreflight ?? false,
      maxRetries,
    });

    console.error("Transaction sent, waiting for confirmation...");

    // Wait for confirmation using non-deprecated API
    const latestBlockhash = await connection.getLatestBlockhash();
    const confirmation = await connection.confirmTransaction({
      signature,
      blockhash: latestBlockhash.blockhash,
      lastValidBlockHeight: latestBlockhash.lastValidBlockHeight,
    }, "confirmed");

    if (confirmation.value.err) {
      console.error("Error: Transaction failed on-chain");
      console.error(JSON.stringify(confirmation.value.err, null, 2));
      process.exit(1);
    }

    // Output signature to stdout
    console.log(signature);

    // Additional info to stderr
    console.error(`\nTransaction confirmed!`);
    console.error(`Signature: ${signature}`);
    console.error(`Explorer: https://solscan.io/tx/${signature}`);
  } catch (error) {
    if (error instanceof SendTransactionError) {
      console.error("Error: Failed to send transaction");
      console.error(`Message: ${error.message}`);

      // Try to get more details
      const logs = error.logs;
      if (logs && logs.length > 0) {
        console.error("\nTransaction logs:");
        logs.forEach((log) => console.error(`  ${log}`));
      }
    } else if (error instanceof Error) {
      console.error(`Error: ${error.message}`);

      // Common error hints
      if (error.message.includes("blockhash")) {
        console.error("\nHint: The transaction's blockhash may have expired.");
        console.error("Request a fresh transaction and try again.");
      } else if (error.message.includes("insufficient")) {
        console.error("\nHint: The wallet may have insufficient SOL for fees.");
      } else if (error.message.includes("429") || error.message.includes("rate")) {
        console.error("\nHint: RPC rate limited. Try a different RPC endpoint.");
        console.error("You can specify one with: --rpc-url <url>");
      }
    } else {
      console.error("Unknown error occurred");
    }
    process.exit(1);
  }
}

// CLI setup
const program = new Command();

program
  .name("send-transaction")
  .description("Send signed transactions to Solana RPC")
  .requiredOption("-t, --signed-tx <base64>", "Base64-encoded signed transaction")
  .option(
    "-r, --rpc-url <url>",
    `RPC endpoint URL (default: ${DEFAULT_RPC_URL}, or SOLANA_RPC_URL env var)`
  )
  .option(
    "--skip-preflight",
    "Skip preflight transaction checks (faster but less safe)"
  )
  .option("--max-retries <number>", "Maximum send retries (default: 3)")
  .action(sendTransaction);

program.parse();

/**
 * utils.ts - Shared utility functions for Jupiter API scripts
 */

/**
 * Gets the Jupiter API key from provided value or environment variable
 */
export function getApiKey(providedKey?: string): string | null {
  if (providedKey) return providedKey;
  if (process.env.JUP_API_KEY) return process.env.JUP_API_KEY;
  return null;
}

/**
 * Prints an error message about missing API key with instructions
 */
export function printApiKeyError(): void {
  console.error(`
Error: Jupiter API key is required.

To get an API key:
  1. Visit https://portal.jup.ag
  2. Create an account and generate an API key
  3. Use it via:
     - --api-key flag: pnpm fetch-api --api-key YOUR_KEY ...
     - Environment variable: export JUP_API_KEY=YOUR_KEY

Rate limits:
  - Free tier: 60 requests/minute
  - Pro tier: Up to 30,000 requests/minute
  - Ultra tier: Dynamic scaling with swap volume
`);
}

/**
 * Validates if a string is valid base64
 */
export function isValidBase64(str: string): boolean {
  if (!str || str.length === 0) return false;

  // Base64 regex: allows A-Z, a-z, 0-9, +, /, and = for padding
  const base64Regex = /^[A-Za-z0-9+/]*={0,2}$/;

  // Check regex and length (must be multiple of 4)
  if (!base64Regex.test(str) || str.length % 4 !== 0) {
    return false;
  }

  // Try to decode to verify
  try {
    Buffer.from(str, "base64");
    return true;
  } catch {
    return false;
  }
}

/**
 * Validates if a string is a valid UUID format
 * Accepts any version of UUID (1-5), not just v4
 */
export function isValidUUID(str: string): boolean {
  if (!str) return false;

  // General UUID format: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
  const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  return uuidRegex.test(str);
}

#!/usr/bin/env tsx
/**
 * wallet-sign.ts - Sign Solana transactions using a local wallet
 *
 * Usage:
 *   pnpm wallet-sign --unsigned-tx "BASE64_TX" --wallet ~/.config/solana/id.json
 *   pnpm wallet-sign --unsigned-tx "BASE64_TX" --wallet /path/to/wallet.json
 *
 * Supports:
 *   - Solana CLI JSON wallet format (array of 64 bytes)
 *
 * SECURITY NOTE: The --wallet flag is required. This script does not accept
 * private keys via command line arguments to prevent exposure in shell history
 * and process listings.
 */

import { Command } from "commander";
import { Keypair, VersionedTransaction } from "@solana/web3.js";
import { readFileSync, existsSync } from "fs";
import { homedir } from "os";
import { join } from "path";

interface SignOptions {
  unsignedTx: string;
  wallet?: string;
}

/**
 * Expand tilde (~) in file paths to the user's home directory
 */
function expandTilde(filePath: string): string {
  if (filePath.startsWith("~")) {
    return join(homedir(), filePath.slice(1));
  }
  return filePath;
}

function loadKeypairFromJson(filePath: string): Keypair {
  const expandedPath = expandTilde(filePath);

  if (!existsSync(expandedPath)) {
    throw new Error(`Wallet file not found: ${expandedPath}`);
  }

  try {
    const fileContent = readFileSync(expandedPath, "utf-8");
    const secretKey = JSON.parse(fileContent);

    if (!Array.isArray(secretKey) || secretKey.length !== 64) {
      throw new Error(
        "Invalid wallet format. Expected JSON array of 64 bytes (Solana CLI format)"
      );
    }

    return Keypair.fromSecretKey(Uint8Array.from(secretKey));
  } catch (error) {
    if (error instanceof SyntaxError) {
      throw new Error(`Invalid JSON in wallet file: ${expandedPath}`);
    }
    throw error;
  }
}

function getKeypair(options: SignOptions): Keypair {
  if (!options.wallet) {
    throw new Error(`
No wallet provided. The --wallet flag is required.

Usage:
  pnpm wallet-sign --unsigned-tx "BASE64_TX" --wallet ~/.config/solana/id.json
  pnpm wallet-sign --unsigned-tx "BASE64_TX" --wallet /path/to/wallet.json

To create a new wallet:
  solana-keygen new -o ~/.config/solana/id.json

SECURITY NOTE: Private keys cannot be passed via command line arguments
to prevent exposure in shell history and process listings.
`);
  }

  return loadKeypairFromJson(options.wallet);
}

async function signTransaction(options: SignOptions): Promise<void> {
  // Load keypair
  let keypair: Keypair;
  try {
    keypair = getKeypair(options);
  } catch (error) {
    if (error instanceof Error) {
      console.error(`Error: ${error.message}`);
    }
    process.exit(1);
  }

  // Decode the unsigned transaction
  let transaction: VersionedTransaction;
  try {
    const txBuffer = Buffer.from(options.unsignedTx, "base64");
    transaction = VersionedTransaction.deserialize(txBuffer);
  } catch (error) {
    console.error("Error: Failed to deserialize transaction");
    console.error("Ensure the transaction is a valid base64-encoded VersionedTransaction");
    process.exit(1);
  }

  // Sign the transaction
  try {
    transaction.sign([keypair]);
  } catch (error) {
    console.error("Error: Failed to sign transaction");
    if (error instanceof Error) {
      console.error(error.message);
    }
    process.exit(1);
  }

  // Serialize and output the signed transaction
  const signedTxBuffer = transaction.serialize();
  const signedTxBase64 = Buffer.from(signedTxBuffer).toString("base64");

  // Output to stdout for piping
  console.log(signedTxBase64);

  // Log signer info to stderr (so it doesn't interfere with piped output)
  console.error(`\nSigned by: ${keypair.publicKey.toBase58()}`);
}

// CLI setup
const program = new Command();

program
  .name("wallet-sign")
  .description(
    "Sign Solana transactions using a local wallet file.\n\n" +
      "SECURITY: Private keys must be stored in wallet files, not passed via\n" +
      "command line arguments (which appear in shell history and process listings)."
  )
  .requiredOption("-t, --unsigned-tx <base64>", "Base64-encoded unsigned transaction")
  .requiredOption(
    "-w, --wallet <path>",
    "Path to Solana CLI JSON wallet file (array of 64 bytes). Supports ~ for home directory."
  )
  .action(signTransaction);

program.parse();
